              <span className="relative z-10 flex items-center gap-2">
                <Icon className={`w-4 h-4 ${isActive ? getActiveColor() : 'text-slate-500'}`} />
                {tab.name}
              </span>
            </Link>
          );
        })}
      </div>
    </div>
  );
}

