            >
              <div className="flex items-center gap-1 mb-0.5">
                <span className="text-2xl font-bold text-white">
                  {metric.value}
                </span>
                {metric.icon && (
                  <metric.icon className={`w-5 h-5 ${getIconColor()}`} />
