                                                                <div className="w-2 h-2 rounded-full bg-[#1152d4]" />
                                                            )}
                                                        </div>
                                                        <span className={`flex-1 ${item.platform === option.value ? "text-[#1152d4] font-medium" : "text-slate-700"}`}>
                                                            {option.label}
                                                        </span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
