"use client";

import { BASE_URL } from "@/services/api.services";
import { useRouter } from "next/navigation";
import React, { createContext, useContext, useState, useEffect } from "react";

interface AuthContextType {
  apiKey: string | null;
  apiSecret: string | null;
  isAuthenticated: boolean;
  currentUser: string | null;
  fullName: string | null;
  role: string | null;
  login: (key: string, secret: string, userData?: { email?: string; fullName?: string; role?: string }) => Promise<void>;
  logout: () => void;
  isInitialized: boolean;
  getCurrentUser: () => Promise<string | null>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children: React.ReactNode }) => {
  const [apiKey, setApiKey] = useState<string | null>(null);
  const [apiSecret, setApiSecret] = useState<string | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [currentUser, setCurrentUser] = useState<string | null>(null);
  const [fullName, setFullName] = useState<string | null>(null);
  const [role, setRole] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState<boolean>(false);
  const router = useRouter();
  const BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL;

  // Load from localStorage on mount
  useEffect(() => {
    const storedKey = localStorage.getItem("apiKey");
    const storedSecret = localStorage.getItem("apiSecret");
    const storedUser = localStorage.getItem("currentUser");
    const storedFullName = localStorage.getItem("fullName");
    const storedRole = localStorage.getItem("role");

    if (storedKey && storedSecret) {
      setApiKey(storedKey);
      setApiSecret(storedSecret);
      setIsAuthenticated(true);
    }

    if (storedUser) {
      setCurrentUser(storedUser);
    }

    if (storedFullName) {
      setFullName(storedFullName);
    }

    if (storedRole) {
      setRole(storedRole);
    }

    setIsInitialized(true);
  }, []);

  // Auto-fetch current user if authenticated but user not known
  useEffect(() => {
    let isMounted = true;

    if (apiKey && apiSecret && !currentUser && isInitialized) {
      getCurrentUser().then((user) => {
        if (isMounted && user) {
          setCurrentUser(user);
          localStorage.setItem("currentUser", user);
        }
      });
    }

    return () => {
      isMounted = false;
    };
  }, [apiKey, apiSecret, currentUser, isInitialized]);

  const getCurrentUser = async (): Promise<string | null> => {
    if (!apiKey || !apiSecret) return null;

    try {
      const response = await fetch(
        "http://103.219.1.138:4412/api/method/frappe.auth.get_logged_user",
        {
          method: "GET",
          headers: {
            Accept: "application/json",
            "Content-Type": "application/json",
            Authorization: `token ${apiKey}:${apiSecret}`,
          },
          credentials: "include",
        }
      );

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      return data.message || null;
    } catch (error) {
      console.error("Error fetching current user:", error);
      return null;
    }
  };

  const login = async (key: string, secret: string, userData?: { email?: string; fullName?: string; role?: string }) => {
    try {
      // Set state immediately
      setApiKey(key);
      setApiSecret(secret);
      setIsAuthenticated(true);

      // Save to localStorage
      localStorage.setItem("apiKey", key);
      localStorage.setItem("apiSecret", secret);

      // If userData is provided, use it
      if (userData) {
        if (userData.email) {
          setCurrentUser(userData.email);
          localStorage.setItem("currentUser", userData.email);
        }
        if (userData.fullName) {
          setFullName(userData.fullName);
          localStorage.setItem("fullName", userData.fullName);
        }
        if (userData.role) {
          setRole(userData.role);
          localStorage.setItem("role", userData.role);
        }
      } else {
        // Fallback: Fetch current user after login
        const user = await getCurrentUser();
        if (user) {
          setCurrentUser(user);
          localStorage.setItem("currentUser", user);
        }
      }
    } catch (error) {
      console.error("Error during login:", error);
      // If error occurs, clean up
      setApiKey(null);
      setApiSecret(null);
      setIsAuthenticated(false);
      setFullName(null);
      setRole(null);
      localStorage.removeItem("apiKey");
      localStorage.removeItem("apiSecret");
      localStorage.removeItem("fullName");
      localStorage.removeItem("role");
    }
  };

const logout = async () => {
  try {
    if (apiKey && apiSecret) {
      await fetch(
        `${BASE_URL}method/stridenex_app.api_stridenex_app.app.logout`,
        {
          method: "POST",
          headers: {
            Accept: "application/json",
            "Content-Type": "application/json",
            Authorization: `token ${apiKey}:${apiSecret}`,
          },
          credentials: "include",
        }
      );
    }
  } catch (error) {
    console.error("Logout API error:", error);
  }

  // Clear state
  setApiKey(null);
  setApiSecret(null);
  setCurrentUser(null);
  setFullName(null);
  setIsAuthenticated(false);

  // Clear localStorage
  localStorage.removeItem("apiKey");
  localStorage.removeItem("apiSecret");
  localStorage.removeItem("posProfile");
  localStorage.removeItem("currentUser");
  localStorage.removeItem("fullName");
  localStorage.removeItem("role");
  localStorage.removeItem("csrfToken");

  // Use setTimeout to ensure state updates complete before redirect
  setTimeout(() => {
    // Force a hard navigation to home page
    window.location.href = "/";
  }, 100);
};

  return (
    <AuthContext.Provider
      value={{
        apiKey,
        apiSecret,
        isAuthenticated,
        currentUser,
        fullName,
        role,
        login,
        logout,
        getCurrentUser,
        isInitialized,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
};

"use client";

import { useState } from "react";
import { ValidationResult } from "@/lib/validators";

interface UseFormValidationProps<T> {
  initialErrors?: Partial<Record<keyof T, string>>;
}

export function useFormValidation<T extends Record<string, any>>(initialErrors = {}) {
  const [errors, setErrors] = useState<Partial<Record<keyof T, string>>>(initialErrors);
  const [touched, setTouched] = useState<Partial<Record<keyof T, boolean>>>({});

  const setFieldError = (field: keyof T, error: string) => {
    setErrors(prev => ({ ...prev, [field]: error }));
  };

  const clearFieldError = (field: keyof T) => {
    setErrors(prev => {
      const newErrors = { ...prev };
      delete newErrors[field];
      return newErrors;
    });
  };

  const setFieldTouched = (field: keyof T) => {
    setTouched(prev => ({ ...prev, [field]: true }));
  };

  const validateField = (
    field: keyof T,
    value: any,
    validator: (value: any) => ValidationResult
  ) => {
    const result = validator(value);
    if (!result.isValid) {
      setFieldError(field, result.error || `${String(field)} is invalid`);
    } else {
      clearFieldError(field);
    }
    return result.isValid;
  };

  const validateAll = (data: T, validators: Partial<Record<keyof T, (value: any) => ValidationResult>>) => {
    let isValid = true;
    const newErrors: Partial<Record<keyof T, string>> = {};

    Object.keys(validators).forEach((key) => {
      const field = key as keyof T;
      const validator = validators[field];
      if (validator) {
        const result = validator(data[field]);
        if (!result.isValid) {
          newErrors[field] = result.error || `${String(field)} is invalid`;
          isValid = false;
        }
      }
    });

    setErrors(newErrors);
    return isValid;
  };

  const hasError = (field: keyof T) => !!errors[field];
  const getError = (field: keyof T) => errors[field];
  const isTouched = (field: keyof T) => !!touched[field];
  const shouldShowError = (field: keyof T) => isTouched(field) && hasError(field);

  return {
    errors,
    touched,
    setFieldError,
    clearFieldError,
    setFieldTouched,
    validateField,
    validateAll,
    hasError,
    getError,
    isTouched,
    shouldShowError,
  };
}

export interface ValidationResult {
  isValid: boolean;
  error?: string;
}

export interface FieldValidation {
  email?: string;
  password?: string;
  confirmPassword?: string;
  required?: Record<string, string>;
}

// Email validation
export const validateEmail = (email: string): ValidationResult => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!email) {
    return { isValid: false, error: "Email is required" };
  }
  if (!emailRegex.test(email)) {
    return { isValid: false, error: "Please enter a valid email address" };
  }
  return { isValid: true };
};

// Password validation
export const validatePassword = (password: string, minLength: number = 8): ValidationResult => {
  if (!password) {
    return { isValid: false, error: "Password is required" };
  }
  if (password.length < minLength) {
    return { isValid: false, error: `Password must be at least ${minLength} characters` };
  }
  return { isValid: true };
};

// Confirm password validation
export const validateConfirmPassword = (password: string, confirmPassword: string): ValidationResult => {
  if (!confirmPassword) {
    return { isValid: false, error: "Please confirm your password" };
  }
  if (password !== confirmPassword) {
    return { isValid: false, error: "Passwords do not match" };
  }
  return { isValid: true };
};

// Required field validation
export const validateRequired = (value: string, fieldName: string): ValidationResult => {
  if (!value || value.trim() === "") {
    return { isValid: false, error: `${fieldName} is required` };
  }
  return { isValid: true };
};

// Multiple fields validation
export const validateFields = (fields: Record<string, any>, rules: Record<string, (value: any) => ValidationResult>): Record<string, string> => {
  const errors: Record<string, string> = {};

  Object.keys(rules).forEach((field) => {
    if (fields[field] !== undefined) {
      const result = rules[field](fields[field]);
      if (!result.isValid) {
        errors[field] = result.error || `${field} is invalid`;
      }
    }
  });

  return errors;
};

// Signup specific validation
export const validateSignupForm = (data: {
  firstName: string;
  lastName: string;
  email: string;
  password: string;
  confirmPassword: string;
  institution?: string;
  selectedRole?: string | null;
  acceptTerms?: boolean;
}) => {
  const errors: Record<string, string> = {};

  // Validate required fields
  if (!data.firstName) errors.firstName = "First name is required";
  if (!data.lastName) errors.lastName = "Last name is required";

  // Validate email
  const emailValidation = validateEmail(data.email);
  if (!emailValidation.isValid) errors.email = emailValidation.error || "Invalid email";

  // Validate password
  const passwordValidation = validatePassword(data.password);
  if (!passwordValidation.isValid) errors.password = passwordValidation.error || "Invalid password";

  // Validate confirm password
  const confirmValidation = validateConfirmPassword(data.password, data.confirmPassword);
  if (!confirmValidation.isValid) errors.confirmPassword = confirmValidation.error || "Passwords do not match";

  // Validate institution for students
  if (data.selectedRole === "student" && !data.institution) {
    errors.institution = "Institution name is required";
  }

  // Validate terms
  if (!data.acceptTerms) {
    errors.terms = "You must accept the Terms of Service and Privacy Policy";
  }

  return errors;
};

// Login specific validation
export const validateLoginForm = (data: { username: string; password: string }) => {
  const errors: Record<string, string> = {};

  if (!data.username) errors.username = "Username or email is required";

  const passwordValidation = validatePassword(data.password);
  if (!passwordValidation.isValid) errors.password = passwordValidation.error || "Password is required";

  return errors;
};

